public int removeDuplicates(int[] nums) {
    if (nums.length <= 2) return nums.length;
    int k = 0, count = 0;
    Integer prev = null;
    for (int x : nums) {
        if (prev != null && x == prev) {
            count++;
        } else {
            count = 1;
            prev = x;
        }
        if (count <= 2) {
            nums[k] = x;
            k++;
        }
    }
    return k;
}

