def removeDuplicates(self, nums: list[int]) -> int:
    if len(nums) <= 2:
        return len(nums)
    k, count, prev = 0, 0, None
    for x in nums:
        if prev is not None and x == prev:
            count += 1
        else:
            count, prev = 1, x
        if count <= 2:
            nums[k] = x
            k += 1
    return k

